const desde = $('Janela').first().json.desde;
const total = Number($input.first().json.total || 0);
const rp = 1000;
const n = Math.max(1, Math.ceil(total / rp)); // sempre 1 pagina, para a normalizacao rodar mesmo com 0 offline
return Array.from({ length: n }, (_, i) => ({ json: { desde, page: i + 1, rp, total } }));

// So queda de enlace conta (fibra ou energia). User-Request, Admin-Reset etc. ficam fora.
const MOTIVOS = new Set(['Lost-Carrier', 'Lost-Service']);
const total = Number($('Paginas').first().json.total || 0);
let lidos = 0;
const porLogin = new Map();
for (const it of $input.all()) {
  for (const r of (it.json.registros || [])) {
    lidos++;
    if (r.online !== 'N' || !MOTIVOS.has(r.motivo_desconexao)) continue;
    const d = r.ultima_conexao_final;
    if (!d || String(d).startsWith('0000')) continue;
    porLogin.set(Number(r.id), { id_login: Number(r.id), desconectou_em: String(d), motivo: r.motivo_desconexao });
  }
}
if (lidos < total * 0.98) throw new Error(`Offline incompleto: ${lidos} de ${total} - ciclo abortado`);
// LGPD: segue so ID, horario e motivo
return [{ json: { off: [...porLogin.values()], lidos } }];
